INSERT INTO public.projects (id, user_id, title, description, city, region, neighborhood, address, postal_code, country, latitude, longitude, category, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, attributes) SELECT 'a6c3c318-4f76-5170-8de7-5230be549f40'::uuid, '34329189-eb9e-5dbb-b1a6-a85e5aa42df5'::uuid, 'Les Résidences Shakira II - Appartement à Tanger', 'Les Résidences Shakira II est un projet immobilier en construction à Tanger, situé dans le quartier Marjane - route de Rabat, en face de McDonald''s Marjane, avec une livraison prévue en octobre 2025. Le projet propose des appartements neufs de 61 à 91 m², composés de 1 à 3 chambres et 1 à 2 salles de bain, avec un prix attractif à partir de 12.500 DH/m². ### Caractéristiques du projet: - Emplacement: Quartier Marjane, Rte de Rabat - Appartements: de 61 à 91 m², 1 à 3 chambres - Salles de bain: 1 à 2 - Parking sous-sol (optionnel) - 2 ascenseurs par immeuble - Climatisation centralisée - Résidence sécurisée et moderne ### À proximité: - Écoles - Centre commercial Marjane - Mosquée - Aéroport de Tanger - Plages Un projet idéal pour un investissement ou une résidence principale à Tanger.', 'Tanger', NULL, 'Route de Rabat', 'Rte de Rabat. Rue des FAR, Enface de McDonald''s Marjane, Route de Rabat, 90000 Tanger', '90000', 'Maroc', NULL, NULL, 'residentiel', 'projet_residentiel', 'en_construction', 'en_commercialisation', 55, '2025-10', NULL, 'https://media.chridari.ma/6efef0ea-b521-43fd-a1af-dfcf46b4d3a0/images/01JZ5BA4KX8XK72Y7851HNREV7-medium.jpg', '["https://media.chridari.ma/6efef0ea-b521-43fd-a1af-dfcf46b4d3a0/images/01JZ5BA4KX8XK72Y7851HNREV7-medium.jpg", "https://media.chridari.ma/800f3244-5453-4be7-bfa4-a4c2f1ea6daf/images/01JZ5BA3M5H123FV5HABDZ9YBA-medium.jpg", "https://media.chridari.ma/452051a3-8fe0-4b58-b5d