INSERT INTO public.projects (id, user_id, title, description, city, region, neighborhood, address, postal_code, country, latitude, longitude, category, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, attributes) SELECT '8a890f51-792a-565e-8ad3-ba8225dc594e'::uuid, 'bbc01261-a78e-5c37-8a16-31dce23382bd'::uuid, 'Les Pins de Maamora - Appartement à Salé', 'Les Pins de Maamora – Salé Al Jadida Découvrez Les Pins de Maamora, une résidence haut standing située aux portes de la forêt de Maamora, offrant un cadre de vie unique alliant confort moderne et sérénité naturelle. Idéal pour les familles et les investisseurs. Les immeubles R+3 disposent d''ascenseurs modernes, de parkings en sous-sol, et d’appartements lumineux aux agencements optimisés. Chaque logement comprend : - Suite parentale avec salle de bain privative - 1 à 2 chambres supplémentaires - Salon spacieux et lumineux - Cuisine équipée avec buanderie - Salle de bain de qualité supérieure - Balcons avec vue sur les jardins ou la forêt Types et prix : - T3 : 72–83 m² - à partir de 850.000 Dhs - T4 : 88–97 m² - à partir de 913.000 Dhs Équipements : Espaces verts, locaux commerciaux, centre de santé, écoles primaires, mosquée, piscine, salle de sport et parkings. Vivez un style de vie moderne en harmonie avec la nature. Livraison : 3ème trimestre 2027', 'Salé', NULL, 'Sala el Jadida', 'Av Lalla Meryem (Zone villas), Sala el Jadida, 11000 Salé', '11000', 'Maroc', NULL, NULL, 'residentiel', 'projet_residentiel', 'en_construction', 'en_commercialisation', 55, '2027-07', NULL, 'https://media.chridari.ma/b655650d-4513-4053-876f-623c7974dab8/images/01JZJHRY7BDW2TR64MCFHMKMPK-medium.jpg', '["https://media.chridari.ma/b655650d-4513-4053-876f-623c7974dab8/images/01JZJHRY7BDW2TR64MCFHMKMPK-medium.jpg", "https://media.chridari.ma/b81891df-0d97-40c1-b10f-49363aa03848/images/01JZJHRXK7JDB0SVN3RNJRT8QK-medium.jpg", "https://media.chridari.ma/f315466a-3555-460d-a60f-ca156f7551c0/images/01JZJHRWR91NW8NG5T3A59PX3Y-medium.jpg", "https://media.chridari.ma/0c4eabf3-3312-45f0-8a73-fb58e607ab35/images/01JZJHRX9HR17AFBHGFHHPV4W5-medium.jpg", "https://media.chridari.ma/8c5e4697-7c88-4eac-92f1-239755ab91b0/images/01JZJHRW78MT04ABSFAV6WJYAJ-medium.jpg", "https://media.chridari.ma/1d717fb8-e65c-420b-a25e-d8dc722cf396/images/01JZJHRVQMS9ATER9T6R13Z6SW-medium.jpg"]'::jsonb, 'Appartement', 'Climatisation · Balcon · Sous-sol · Concierge · Ascenseur · Issue de secours · Cuisine équipée · Chauffage · Parking · Aire de jeux · Piscine · Terrasse', 'Salle de sport · Hôpital · Mosquée · Centre commercial · École', FALSE, 850000, 850000, 913000, 'MAD', '72–97 m2', 'CHR-PRM-36zoy', 'Chaabi Lil Iskane', 'https://chridari.ma/fr/promoters/chaabi-lil-iskane-36zoy', '{"seed_batch": "projets_pros_289", "source_project_id": "2bdda584-9a91-590f-8a23-2d6d7fe022ba", "source_url": "https://chridari.ma/fr/projects/les-pins-de-maamora-appartement-local-commercial-sale-phzbwj", "professionnel_nom": "SITCA", "description_courte": "Appartements T3 & T4 à Salé Al Jadida, près de la forêt de Maamora. Les Pins de Maamora allie confort, verdure et cadre moderne.", "architecte": "AWA ARCHITECTS (Tachrone « imm Firdaous ») — portfolio promoteur", "bureau_etudes": null, "entreprises_construction": "Benapro (Tachrone « Différents projets de construction ») — portfolio promoteur", "equipe_realisation_mentions": "Architecte: AWA ARCHITECTS — Tachrone « imm Firdaous » (https://tachrone.ma/fr/profil/awa-architects/716) [portfolio promoteur] | Architecte: Khaoula naimi architects — Tachrone « Foyer de la femme » (https://tachrone.ma/fr/profil/khaoula-naimi-architects/4692) [portfolio promoteur] | Entreprise: Benapro — Tachrone « Différents projets de construction » (https://tachrone.ma/fr/profil/benapro/4051) [portfolio promoteur] | Entreprise: SITCA — Tachrone « Construction villa à Marrakech » (https://tachrone.ma/fr/profil/sitca/284) [portfolio promoteur]", "chambres_min": "2", "chambres_max": "3", "nb_offres": "2"}'::jsonb WHERE EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = 'bbc01261-a78e-5c37-8a16-31dce23382bd'::uuid);
