INSERT INTO public.projects (id, user_id, title, description, city, region, neighborhood, address, postal_code, country, latitude, longitude, category, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, attributes) SELECT 'bf320c4b-2c53-5b60-830a-1a09bf386b84'::uuid, 'bbc01261-a78e-5c37-8a16-31dce23382bd'::uuid, 'Riad Garden 2 - Appartement à Marrakech', 'Riad Garden 2 - Agdal, Marrakech Découvrez Riad Garden 2, une résidence haut standing idéalement située sur l''avenue Mohammed VI, au prestigieux quartier Agdal de Marrakech. Cette nouvelle tranche allie élégance, raffinement et confort, pour un cadre de vie adapté aux familles comme aux investisseurs. ### Points forts: - Appartements de 84 à 116 m² - Prix à partir de 1.830.000 DH - Résidence R+2 avec ascenseurs - 2 chambres, 2 salles de bain, grand salon, balcons & terrasses - Finitions haut de gamme et agencement optimisé - Piscines, jardins paysagers et vue imprenable sur l’Atlas - Environnement sécurisé et pensé pour le bien-être ### Localisation & style de vie: - Située sur l’avenue Mohammed VI, Agdal - l''une des adresses les plus prestigieuses de Marrakech - À proximité des restaurants, hôtels de luxe et centres commerciaux - Idéal comme résidence principale ou investissement immobilier premium Livraison : 4ème trimestre 2027 Riad Garden 2 vous invite à adopter un art de vivre où confort moderne et élégance intemporelle se rencontrent au cœur de Marrakech.', 'Marrakech', NULL, 'Agdal', 'Av Mohammed VI, Agdal, 40000 Marrakech', '40000', 'Maroc', NULL, NULL, 'residentiel', 'projet_residentiel', 'en_construction', 'en_commercialisation', 55, '2027-10', NULL, 'https://media.chridari.ma/4cd060f4-76fc-4ac2-9777-fe7b249db864/images/01JZJCCER0X9T30Z4T8DR98ZY4-medium.jpg', '["https://media.chridari.ma/4cd060f4-76fc-4ac2-9777-