INSERT INTO public.projects (id, user_id, title, description, city, region, neighborhood, address, postal_code, country, latitude, longitude, category, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, attributes) SELECT 'ca6805fd-53bd-5ad7-9cdb-73978c475fe9'::uuid, 'bbc01261-a78e-5c37-8a16-31dce23382bd'::uuid, 'Océane - Villa à Sidi Rahal', 'Océane - Pavillons - Sidi Rahal À seulement 5 minutes du centre de Sidi Rahal, découvrez Océane, une résidence haut standing en bord de mer alliant luxe, nature et confort. Avec piscines et accès direct à la plage, ce projet offre un cadre de vie idéal pour une résidence principale ou secondaire. ### Points forts : - Villas en R+1 de 151 m² - Architecture contemporaine et finitions haut de gamme - Intérieurs spacieux et lumineux avec baies vitrées - Rez-de-chaussée : salon, cuisine équipée moderne, salle de bain - Étage : 2 grandes chambres avec balcon/terrasse + salle de bain - Jardins et piscines privés en option ### Localisation & cadre de vie: - Situé sur la route côtière d''Azemmour, à deux pas de la mer - Accès direct à la plage et vues imprenables - Proximité : centre commercial, cafés, restaurants, aires de jeux et espaces verts ### Livraison: 4ème trimestre 2027 Océane Pavillons, l''équilibre parfait entre élégance, sérénité et modernité.', 'Sidi Rahal', NULL, 'Haouzia', 'Route d''Azemmour, Haouzia, 24100 Sidi Rahal', '24100', 'Maroc', NULL, NULL, 'residentiel', 'projet_residentiel', 'en_construction', 'en_commercialisation', 55, '2027-10', NULL, 'https://media.chridari.ma/c7c02f70-9ed9-411d-82ea-f9988d4b77cb/images/01JZJKKK2CQXHCGH5DWSVWDC47-medium.jpg', '["https://media.chridari.ma/c7c02f70-9ed9-411d-82ea-f9988d4b77cb/images/01JZJKKK2CQXHCGH5DWSVWDC47-medium.jpg", "https://media.chridari.ma/7df911e2-e8c5-4e04-951c-8c2705e25b