INSERT INTO public.projects (id, user_id, title, description, city, region, neighborhood, address, postal_code, country, latitude, longitude, category, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, attributes) SELECT 'f6af53fb-d6be-5708-84f6-c3f6f047ddf8'::uuid, '6c1d2318-dee2-5959-8a69-75888f777e49'::uuid, 'Résidence Oasis - Studio, Appartement, Duplex, Local Commercial à Agadir', 'Résidence Oasis - Vivez la sérénité au cœur d''Agadir Située dans le quartier recherché de Hay El Houda, la Résidence Oasis est un projet immobilier sur plan qui propose une diversité d’unités modernes adaptées à tous les styles de vie: studios, appartements, duplex et locaux commerciaux. Pensée pour offrir un cadre de vie harmonieux, la résidence combine une architecture contemporaine, des finitions soignées et un emplacement stratégique à proximité des commodités de la ville. ### Détails du projet: - Typologies : studios, appartements, duplex, commerces - 1 à 3 chambres, 1 à 2 salles de bain - Superficie variée, avec un prix à partir de 12 000 DH/m² - Prix minimum des unités : 442 000 DH - Livraison prévue: Décembre 2028 Profitez d''un investissement sûr et rentable dans un quartier en plein essor, avec des logements conçus pour allier confort, luminosité et fonctionnalité.', 'Agadir', NULL, 'Hay El Houda', 'Avenue Mohammed El Fassi, Hay El Houda, 80010 Agadir', '80010', 'Maroc', NULL, NULL, 'mixte', 'projet_mixte', 'sur_plan', 'en_commercialisation', 15, '2028-12', NULL, 'https://media.chridari.ma/50fdf8c8-9903-4aa3-b704-0d218a09d686/images/01JZJQ36HE09S9TQJGQ04F05AB-medium.jpg', '["https://media.chridari.ma/50fdf8c8-9903-4aa3-b704-0d218a09d686/images/01JZJQ36HE09S9TQJGQ04F05AB-medium.jpg", "https://media.chridari.ma/ba7813e7-45a6-4d71-85bd-b225c8297885/images/01JZJQ35KTXCE45X89A691T8N3-m