INSERT INTO public.projects (id, user_id, title, description, city, region, neighborhood, address, postal_code, country, latitude, longitude, category, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, attributes) SELECT '018cb22f-962a-5634-b330-4f16338b1d93'::uuid, 'b4af7e55-9043-53a5-8a38-21cf8e5f0908'::uuid, 'Lotissement Al Bassatine : Lots de terrain R+2, Lots de terrain R+3 à Safi', 'Le projet “Lotissement Al Bassatine” propose des parcelles en R+2 et R+3 dès 100m² avec rez-de-chaussée pour usage résidentiel ou commercial. Il intègre une mosquée, hammam, écoles et un poste de police, offrant un cadre de vie complet. Idéalement situé à 1 km de la route menant à “Tlat Bougedra”, il est bien relié à l’autoroute de Casablanca et la route nationale de Marrakech. À seulement 8 minutes du centre-ville de Safi, il assure un accès facile à la vie urbaine, tout en étant proche d’écoles, d’une mosquée, du centre commercial “Marjane”, du complexe sportif Olympique Safi, de la clinique Akdital et de l’hôpital Multidisciplinaire Sheikh Zayed. Un choix idéal pour résider ou investir.', 'Safi', NULL, 'menant à “Tlat Bougedra”', 'km 1 route Tlet Bougedra, Rouamcha', '46000', 'Maroc', NULL, NULL, 'mixte', 'projet_mixte', 'en_construction', 'non_determine', 55, NULL, NULL, 'https://alliancesdarna.ma/wp-content/uploads/Lotissement-Al-Bassatine.jpg', '["https://alliancesdarna.ma/wp-content/uploads/Lotissement-Al-Bassatine.jpg", "https://alliancesdarna.ma/wp-content/uploads/mosque.png", "https://alliancesdarna.ma/wp-content/uploads/ecole.png", "https://alliancesdarna.ma/wp-content/uploads/hamam.png", "https://alliancesdarna.ma/wp-content/uploads/police-1.png", "https://alliancesdarna.ma/wp-content/uploads/four-1.png", "https://alliancesdarna.ma/wp-content/uploads/menzah-benslimane-lot-terra