INSERT INTO public.projects (id, user_id, title, description, city, region, neighborhood, address, postal_code, country, latitude, longitude, category, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, attributes) SELECT '1f3adf6e-c370-57c9-8d47-d2bdcc1569ca'::uuid, 'b503f3fa-287f-504b-b657-f3bcfc5edaba'::uuid, 'Natura Living - Appartement à Mohammedia', '### Natura Living - Le confort urbain au cœur de la nature Situé au centre de Mohammedia, le projet Natura Living du Groupe Allali propose une expérience résidentielle unique où la nature est au cœur de chaque détail. Il s’agit de bien plus qu’une simple résidence, avec ses appartements 2 chambres allant de 87 à 98 m², alliant modernité, sérénité et accessibilité. Chaque logement offre : - Des espaces lumineux et bien agencés - Des finitions haut de gamme et matériaux nobles - Une atmosphère paisible en plein cœur urbain ### Équipements disponibles : - Piscines intérieure et extérieure - Salle de sport entièrement équipée - Kids Club sécurisé ### Points d’intérêt à proximité : - En face du stade El Bachir - À seulement 2 minutes du Parc Floral Un cadre de vie raffiné et naturel, idéal pour une résidence principale ou un investissement intelligent.', 'Mohammedia', NULL, 'Wafa', 'Boulevard Zenata, Wafa, 28800 Mohammedia', '28800', 'Maroc', NULL, NULL, 'mixte', 'projet_mixte', 'pret_a_livrer', 'en_commercialisation', 90, NULL, NULL, 'https://media.chridari.ma/e3a38981-45c8-4145-9dc5-349700e5f5be/images/01JY1946FC9RD4WD91GS6Y26WG-medium.jpg', '["https://media.chridari.ma/e3a38981-45c8-4145-9dc5-349700e5f5be/images/01JY1946FC9RD4WD91GS6Y26WG-medium.jpg", "https://media.chridari.ma/9e40330a-8881-4dd6-b1a2-d4700df43848/images/01JY1944P74YYNANVYTBFZZF7M-medium.jpg", "https://media.chridari.ma/8c42c46b-0f48-42ff-a513-a507fdbbdfd9/images/01JY194895S62W710KJ1942CVM-medium.jpg", "https://media.chridari.ma/cdee67c3-99e3-417b-8b2c-4a1f5e9b6dd7/images/01JY194AMR8JB9XEX0PNMTPBX3-medium.jpg"]'::jsonb, 'Appartement', 'Piscine · Jardin · Parking · Aire de jeux', 'Plage · Mosquée · École · Stade', FALSE, 1174000, 1174000, 1175000, 'MAD', '87–98 m2', 'CHR-PRM-5pu6t', 'Groupe Allali', 'https://chridari.ma/fr/promoters/groupe-allali-5pu6t', '{"seed_batch": "projets_pros_289", "source_project_id": "89bc314d-e5b7-5dc8-9ef9-e8f8904f2fa0", "source_url": "https://chridari.ma/fr/projects/natura-living-appartement-mohammedia-sweq8o", "professionnel_nom": "Agence d''architecture et d''aménagement TAHTI - 3AT", "description_courte": "Natura Living à Mohammedia propose des appartements 2 chambres de 87 à 98 m². Finitions haut de gamme, espaces verts, piscines, livraison immédiate.", "architecte": "Agence d''architecture et d''aménagement TAHTI - 3AT (Tachrone)", "bureau_etudes": null, "entreprises_construction": null, "equipe_realisation_mentions": "Architecte: Agence TAHTI - 3AT — réalisation Tachrone « NATURA LIVING » | Architecte: Agence d''architecture et d''aménagement TAHTI - 3AT — Tachrone « NATURA LIVING » (https://tachrone.ma/fr/profil/agence-darchitecture-et-damenagement-tahti-3at/7353)", "chambres_min": "2", "chambres_max": "2", "nb_offres": "2"}'::jsonb WHERE EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = 'b503f3fa-287f-504b-b657-f3bcfc5edaba'::uuid);
INSERT INTO public.projects (id, user_id, title, description, city, region, neighborhood, address, postal_code, country, latitude, longitude, category, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, attributes) SELECT 'a1454358-224f-5596-ac1b-dd0d8bc76f02'::uuid, 'bbc01261-a78e-5c37-8a16-31dce23382bd'::uuid, 'Patio Verde - Studio, Appartement à Mohammedia', 'Découvrez Patio Verde, une résidence haut standing signée Chaabi Lil Iskane, idéalement située sur la Corniche de Mohammedia, au croisement de l’avenue Hassan II et de la rue d’Agadir, à quelques pas de la mer. Cette résidence allie design moderne, confort et sécurité, pour un cadre de vie raffiné. #### Points forts: - Résidence R+5 avec ascenseurs modernes et parkings souterrains - Studios et appartements spacieux: - T2: 45–82 m² - à partir de 580.000 Dhs - T3: 88–135 m² - à partir de 990.000 Dhs - T4: 105–142 m² - à partir de 1.207.000 Dhs - Séjours lumineux et cuisines équipées avec buanderie - 1 à 3 chambres, incluant suite parentale avec dressing - Balcons et terrasses avec vue sur la ville ou le jardin - Finitions haut de gamme et matériaux raffinés - Environnement sécurisé avec espaces verts paysagers #### Localisation et style de vie: - Sur l''avenue Hassan II et rue d’Agadir, Corniche Mohammedia - Proche de plages, cafés, restaurants et parcs - Idéal pour résidence principale, maison de vacances ou investissement Livraison: 2ᵉ trimestre 2026 Patio Verde offre le parfait équilibre entre élégance moderne, sérénité côtière et confort urbain pour toute la famille.', 'Mohammedia', NULL, 'Corniche', 'Av Hassan II, Rue d''Agadir, Corniche, 28800 Mohammedia', '28800', 'Maroc', NULL, NULL, 'residentiel', 'projet_residentiel', 'en_construction', 'en_commercialisation', 55, '2026-04', NULL, 'https://media.chridari.ma/0