INSERT INTO public.projects (id, user_id, title, description, city, region, neighborhood, address, postal_code, country, latitude, longitude, category, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, attributes) SELECT '25054fc8-9c37-583d-901a-2059eb2c7ff4'::uuid, 'f38162db-3845-5217-bf68-a9fa9aa6cb6c'::uuid, 'Patio Verde - Studio, Appartement à Mohammedia', 'Découvrez Patio Verde, une résidence haut standing signée Chaabi Lil Iskane, idéalement située sur la Corniche de Mohammedia, au croisement de l’avenue Hassan II et de la rue d’Agadir, à quelques pas de la mer. Cette résidence allie design moderne, confort et sécurité, pour un cadre de vie raffiné. #### Points forts: - Résidence R+5 avec ascenseurs modernes et parkings souterrains - Studios et appartements spacieux: - T2: 45–82 m² - à partir de 580.000 Dhs - T3: 88–135 m² - à partir de 990.000 Dhs - T4: 105–142 m² - à partir de 1.207.000 Dhs - Séjours lumineux et cuisines équipées avec buanderie - 1 à 3 chambres, incluant suite parentale avec dressing - Balcons et terrasses avec vue sur la ville ou le jardin - Finitions haut de gamme et matériaux raffinés - Environnement sécurisé avec espaces verts paysagers #### Localisation et style de vie: - Sur l''avenue Hassan II et rue d’Agadir, Corniche Mohammedia - Proche de plages, cafés, restaurants et parcs - Idéal pour résidence principale, maison de vacances ou investissement Livraison: 2ᵉ trimestre 2026 Patio Verde offre le parfait équilibre entre élégance moderne, sérénité côtière et confort urbain pour toute la famille.', 'Mohammedia', NULL, 'Corniche', 'Av Hassan II, Rue d''Agadir, Corniche, 28800 Mohammedia', '28800', 'Maroc', NULL, NULL, 'residentiel', 'projet_residentiel', 'en_construction', 'en_commercialisation', 55, '2026-04', NULL, 'https://media.chridari.ma/0