INSERT INTO public.projects (id, user_id, title, description, city, region, neighborhood, address, postal_code, country, latitude, longitude, category, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, attributes) SELECT 'a914579f-9f4e-5f64-a04d-880bd8efc3f2'::uuid, '2122bcce-d7fe-5b47-82a4-d5fa980e18c6'::uuid, 'Logements Essalam', 'Essalam Tarfaya est un projet résidentiel moderne idéalement situé dans une zone en plein développement, offrant un cadre de vie calme et accessible. Il propose des appartements de type F3, parfaitement agencés, avec des surfaces adaptées aux besoins des familles. Chaque logement comprend un salon lumineux, deux chambres confortables, une cuisine fonctionnelle et des finitions soignées. Le projet bénéficie d’une implantation intelligente avec des espaces organisés et des stationnements intégrés. Son emplacement stratégique à Tarfaya en fait une opportunité idéale pour habiter ou investir. La commercialisation débutera le 11 août 2026.', 'Agadir', NULL, 'en plein développement', 'Dakhla, à pr... Plus d''infos Groupe AL OMRANE - Logements Essalam العربية × Bienvenue SAO - Agence Heure de connexion :', '80000', 'Maroc', NULL, NULL, 'mixte', 'projet_mixte', 'en_construction', 'en_commercialisation', 55, NULL, NULL, 'https://alomrane.gov.ma/var/alomrane/storage/images/_aliases/image_gallery_line/alomrane/notre-reseau/al-omrane-al-janoub/produits/projets/logements-essalam/13783886-1-fre-FR/Logements-Essalam.jpg', '["https://alomrane.gov.ma/var/alomrane/storage/images/_aliases/image_gallery_line/alomrane/notre-reseau/al-omrane-al-janoub/produits/projets/logements-essalam/13783886-1-fre-FR/Logements-Essalam.jpg", "https://alomrane.gov.ma/var/alomrane/storage/images/_aliases/product_list/alomrane/notre-reseau/al-omrane-al-janoub/produits/projets/projet-a