INSERT INTO public.projects (id, user_id, title, description, city, region, neighborhood, address, postal_code, country, latitude, longitude, category, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, attributes) SELECT 'ca4df440-5018-548c-b757-226e02756865'::uuid, 'bbc01261-a78e-5c37-8a16-31dce23382bd'::uuid, 'Al Anbar - Appartement, Duplex à Marrakech', 'Résidence Al Anbar - M''hamid Sud, Marrakech À partir de 560.000 Dhs, la Résidence Al Anbar est idéalement située sur l''avenue Guemassa, dans le quartier dynamique de M-hamid Sud. Proche des écoles, commerces, transports et services quotidiens, elle allie confort, sécurité et praticité urbaine. Les bâtiments R+4 disposent d’ascenseurs modernes, d’un parking souterrain sécurisé, et proposent des appartements et duplex avec des finitions haut de gamme et des espaces optimisés. Types d’appartements & prix : - T3 : 72 à 87 m² - à partir de 560.000 Dhs - T4 : 73 à 122 m² - à partir de 700.000 Dhs Équipements du projet et à proximité : Espaces verts Aires de jeux Centre commercial (prochainement) Centre de santé Commerces Écoles & université Mosquée Places de parking Terrains de sport La résidence est éligible au programme d’aide directe au logement (70.000 Dhs), offrant un environnement convivial et moderne pour toute la famille.', 'Marrakech', NULL, 'M''Hamid', 'Avenue Guemassa, M''Hamid Sud, M''Hamid, 40000 Marrakech', '40000', 'Maroc', NULL, NULL, 'residentiel', 'projet_residentiel', 'en_construction', 'en_commercialisation', 55, '2026-07', NULL, 'https://media.chridari.ma/bb4f2630-2e80-4425-ae18-6fc7818c8df9/images/01JZMMQXSPDS9HTM2KATCAZKN2-medium.jpg', '["https://media.chridari.ma/bb4f2630-2e80-4425-ae18-6fc7818c8df9/images/01JZMMQXSPDS9HTM2KATCAZKN2-medium.jpg", "https://media.chridari.ma/b52933a3-e5be-477f-8a90-709db