INSERT INTO public.projects (id, user_id, title, description, city, region, neighborhood, address, postal_code, country, latitude, longitude, category, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, attributes) SELECT 'cbe63b41-9a40-5d00-8731-82e7a6113895'::uuid, 'eeea4c89-6318-59d8-88bd-f9f5391ac809'::uuid, 'Les Orchidées', 'Le projet Les Orchidées est un lotissement résidentiel de standing, idéalement situé au cœur de la ville de Selouane, bénéficiant d’un emplacement stratégique et privilégié. Le projet propose des lots de terrains en R+1 à usage résidentiel, ainsi que des lots en R+2 et R+3 destinés à un usage commercial. Il comprend également des parcelles dédiées à la construction de villas, le tout dans un environnement moderne, harmonieux et répondant à des standards de qualité élevés. La commercialisation à guichet ouvert à partir du 16 Octobre 2026.', 'Oujda', NULL, 'fath à Selouane Villa N', 'u cœur de la ville de Selouane, bénéficiant d’un emplacement stratégique et privilégié. Le projet propose des lots de te', '60000', 'Maroc', NULL, NULL, 'residentiel', 'projet_residentiel', 'en_construction', 'en_commercialisation', 55, NULL, NULL, 'https://alomrane.gov.ma/var/alomrane/storage/images/_aliases/image_gallery_line/alomrane/notre-reseau/al-omrane-region-de-l-oriental/produits/projets/les-orchidees/14480455-1-fre-FR/Les-Orchid%C3%A9es.jpg', '["https://alomrane.gov.ma/var/alomrane/storage/images/_aliases/image_gallery_line/alomrane/notre-reseau/al-omrane-region-de-l-oriental/produits/projets/les-orchidees/14480455-1-fre-FR/Les-Orchid%C3%A9es.jpg", "https://alomrane.gov.ma/var/alomrane/storage/images/_aliases/product_list/alomrane/notre-reseau/al-omrane-region-de-l-oriental/produits/projets/residence-riad-al-yassamine/14385675-1-fre-FR/R%C3%A9sidence-Riad-Al-Yas