INSERT INTO public.projects (id, user_id, title, description, city, region, neighborhood, address, postal_code, country, latitude, longitude, category, project_type, status, commercial_status, progress, expected_end, actual_end, cover_image, images, typologies, equipment, nearby, price_on_request, price_from, price_min, price_max, currency, surface, promoter_id, promoter_name, promoter_website, attributes) SELECT '0562dbd9-025c-5485-b4c5-f0a57f577d38'::uuid, '606ae6b8-73cc-56a7-8a76-dbc4e82100ad'::uuid, 'Renaissance Hamza 1 - Villa à Fès', '### Renaissance HAMZA 1 – Fes ### Présentation du projet Renaissance HAMZA 1 est situé dans le quartier résidentiel Hamza 1 à Fès, offrant un environnement de vie paisible et raffiné. Le projet est conçu pour créer une harmonie entre la vie moderne et la sérénité quotidienne. ### Un cadre résidentiel agréable - Quartier calme et bien organisé - Environnement idéal pour les familles et la vie à long terme - Architecture élégante en harmonie avec son environnement - Atmosphère tranquille favorisant le bien-être quotidien ### Un style de vie raffiné Renaissance HAMZA 1 Le projet allie tranquillité, sécurité et proximité immédiate des commodités, tout en assurant une excellente valorisation à long terme. Les villas sont implantées sur des terrains de 355 m² à 426 m² et disposent d’une surface totale habitable de 403 m² à 494 m², réparties sur trois niveaux : sous-sol, rez-de-chaussée et premier étage.', 'Fès', NULL, 'Hamza 1', 'Route d’Imouzzer, Hamza 1, 30050 Fès', '30050', 'Maroc', NULL, NULL, 'residentiel', 'projet_residentiel', 'pret_a_livrer', 'en_commercialisation', 90, '2026-03', NULL, 'https://media.chridari.ma/ea390ae7-35fd-4a3c-8cb6-3f115b073b88/images/01KD8CSJRTHFGJAPVPQW2V4A0N-medium.jpg', '["https://media.chridari.ma/ea390ae7-35fd-4a3c-8cb6-3f115b073b88/images/01KD8CSJRTHFGJAPVPQW2V4A0N-medium.jpg", "https://media.chridari.ma/c443294c-b834-4110-b39d-288ac8e414be/images/01KD8CSMFS6CNYXQHKYC8Q1XZQ-medium.jpg", "https://media.chridari.ma/0cb9447c-6358-4054-be13-55dcd78e40cd/images/01KD8CSP90RERSWTNY2DDVWFNN-medium.jpg", "https://media.chridari.ma/e5e03ab5-e944-4621-8363-62556254275a/images/01KD8CSR5GEG7QWNDWM7S9884D-medium.jpg", "https://media.chridari.ma/2e7c4fdd-34c6-4de5-95ff-7b0c4ae15fd8/images/01KD8CSSN46QPA98Q9XNH0Y95G-medium.jpg", "https://media.chridari.ma/cc961f86-abd3-486d-9188-86d42c276d7e/images/01KD8CSVCB98NJ6F3ZDD9EVXDA-medium.jpg", "https://media.chridari.ma/2ff97c54-396c-4cb7-95a2-ec407d3fd049/images/01KD8CSX5XACHCAF4MVT0E7CGH-medium.jpg", "https://media.chridari.ma/e73b8b3a-fb60-4db3-9203-6872559129bf/images/01KD8CSZ1WER0MP4GDM7PZ4B6X-medium.jpg", "https://media.chridari.ma/fbdac604-257c-4c12-992d-7ff808fd5182/images/01KD8CT0FEJNJ7G4H13C2VNFR5-medium.jpg", "https://media.chridari.ma/4027ead9-3015-417c-b98f-05572da5c49b/images/01KD8CT1ZDVYFM5Q87QSXXMBW4-medium.jpg"]'::jsonb, 'Villa', 'Climatisation · Balcon · Sous-sol · Dressing · Cuisine équipée · Cheminée · Garage · Jardin · Piscine · Terrasse · Interphone vidéo', 'Station-service · Hôpital · Salle de sport · Café · Mosquée · Pharmacie · École · Université · Supermarché', FALSE, 4800000, 3500000, 4800000, 'MAD', '403–494 m2', 'CHR-PRM-n8ji8c', 'Groupe Ryham', 'https://chridari.ma/fr/promoters/groupe-ryham-n8ji8c', '{"seed_batch": "projets_pros_289", "source_project_id": "f1bbcb46-e2c8-5f51-b06a-9f172b2c3d35", "source_url": "https://chridari.ma/fr/projects/renaissance-hamza-1-villa-fes-8xm0ec", "professionnel_nom": "ALQUIMAROC", "description_courte": "Renaissance Hamza 1 à Fès propose des villas de standing aux espaces généreux, finitions haut de gamme, équipements complets et emplacement privilégié.", "architecte": null, "bureau_etudes": null, "entreprises_construction": null, "equipe_realisation_mentions": "sous_traitants: ALQUIMAROC — Hamza Assim‏ - ‏Technicien spécialisé en génie civil (https://ma.linkedin.com/in/hamza-assim-813649322)", "chambres_min": "6", "chambres_max": "6", "nb_offres": "2"}'::jsonb WHERE EXI