ps://media.chridari.ma/ab191aa3-f146-4b73-ade7-762e4ca1b158/images/01JXZDHHHNJ41DV9015JTKBJYN-medium.jpg", "https://media.chridari.ma/e60b7cbb-d6f9-497c-9a61-74e98f2a65a0/images/01JXZDTQHAFR5HVEKDQXTNV56P-medium.jpg", "https://media.chridari.ma/02838d04-ac16-465b-8152-ba91146ce5db/images/01JXZDTW93VVYFRCPF36WJAP40-medium.jpg", "https://media.chridari.ma/5696f8a0-2801-4f23-86a6-74c11d4aab0a/images/01JXZDTY92K5A5ANZ4YEBYVWJM-medium.jpg"]'::jsonb, 'Appartement · Local commercial', 'Piscine · Balcon · Climatisation · Cuisine équipée · Jardin', 'Plage · Salle de sport · Mosquée · École', FALSE, 1190000, 1190000, 1190000, 'MAD', '27–110 m2', 'CHR-PRM-5pu6t', 'Groupe Allali', 'https://chridari.ma/fr/promoters/groupe-allali-5pu6t', '{"seed_batch": "projets_pros_289", "source_project_id": "ff4ba2f1-c0bc-545a-9edf-7414fceffda4", "source_url": "https://chridari.ma/fr/projects/m-ocean-appartement-local-commercial-mohammedia-744ru9", "professionnel_nom": "Agence d''architecture et d''aménagement TAHTI - 3AT", "description_courte": "Découvrez M OCEAN à Mohammedia par le Groupe Allali, des appartements de 1 à 3 chambres entre 85 et 110m², à 2 min de la plage, avec piscine, salle de sport et kids club.", "architecte": "Abdelkerim Tahti (Agence d''Architecture et d''Aménagement TAHTI — 3AT)", "bureau_etudes": null, "entreprises_construction": "BATEMA", "equipe_realisation_mentions": "Dossier candidature Groupe Allali (FlipHTML5) : projet MANESMANE / M Ocean — architecte Abdelkrim TAHTI ; GO BATEMA ; MOA Groupe Allali.", "chambres_min": "1", "chambres_max": "3", "nb_offres": "2"}'::jsonb WHERE EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = 'b503f3fa-287f-504b-b657-f3bcfc5edaba'::uuid);
